const EVIDENCE_FILES={"gdb-analysis":"","qaqc":"","standards":"","terrapulse":"","ops-dashboard":"","climate-system":"","satellite-qa-report":"","hydro-gis-system":"","geoai-dashboard":"","rainfed-agric-app":"","geosite-dashboard":""};
let currentEvidence=null;
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
function decode64(v){const b=atob(v),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);return new TextDecoder().decode(u)}
function evidenceText(id){return IS_PACKAGE?null:decode64(EVIDENCE_FILES[id])}
function evidenceBlob(id){return new Blob([evidenceText(id)||''],{type:'text/html;charset=utf-8'})}

function scrollEvidence(direction){const rail=document.getElementById('evidenceCarousel');if(!rail)return;const amount=Math.max(360,Math.floor(rail.clientWidth*0.84));rail.scrollBy({left:direction*amount,behavior:'smooth'});}
 function openEvidence(id){
 currentEvidence=id;const m=EVIDENCE_META[id];$('#viewerTitle').textContent=m.title;$('#viewerType').textContent=m.type;
 $('#contextType').textContent=m.type;$('#contextTitle').textContent=m.title;$('#contextSummary').textContent=m.summary;
 $('#contextDemonstrates').innerHTML=m.demonstrates.map(x=>`<li>${x}</li>`).join('');
 $('#contextProjects').innerHTML=m.projects.map(x=>`<span class="chip">${x}</span>`).join('');
 $('#contextCapabilities').innerHTML=m.capabilities.map(x=>`<span class="chip">${x}</span>`).join('');
 $('#evidenceSwitches').innerHTML=Object.entries(EVIDENCE_META).map(([k,v])=>`<button class="switch ${k===id?'active':''}" onclick="openEvidence('${k}')">${v.title}</button>`).join('');
 const frame=$('#viewerFrame'); if(IS_PACKAGE){frame.removeAttribute('srcdoc');frame.src=m.path}else{frame.removeAttribute('src');frame.srcdoc=evidenceText(id)}
 $('#viewerProject').onclick=()=>{closeViewer();document.getElementById(m.section).scrollIntoView({behavior:'smooth'});highlight(document.getElementById(m.section))};
 $('#viewerFull').onclick=()=>openEvidenceFull(id);
 $('#viewer').classList.add('open');document.body.classList.add('lock');
}
function closeViewer(){const f=$('#viewerFrame');f.src='about:blank';f.removeAttribute('srcdoc');$('#viewer').classList.remove('open');$('#viewerContext').classList.remove('open');document.body.classList.remove('lock')}
function openEvidenceFull(id=currentEvidence){if(!id)return;const m=EVIDENCE_META[id];if(IS_PACKAGE){window.open(m.path,'_blank','noopener')}else{const u=URL.createObjectURL(evidenceBlob(id));window.open(u,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(u),90000)}}
$('#viewerDetails').onclick=()=>$('#viewerContext').classList.toggle('open');

// Header, reading progress and scroll spy.
const sections=$$('main section[id]');const navLinks=$$('.nav a');
function onScroll(){const y=scrollY, max=document.documentElement.scrollHeight-innerHeight;$('#progress').style.width=(max?y/max*100:0)+'%';$('#backTop').classList.toggle('show',y>700);let current='';for(const s of sections){if(s.offsetTop<=y+130)current=s.id}navLinks.forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+current))}
addEventListener('scroll',onScroll,{passive:true});onScroll();$('#backTop').onclick=()=>scrollTo({top:0,behavior:'smooth'});$('#printButton').onclick=()=>print();
$('#menuButton').onclick=()=>$('#mobileMenu').classList.toggle('open');$$('#mobileMenu a').forEach(a=>a.onclick=()=>$('#mobileMenu').classList.remove('open'));
let scale=1;function setScale(v){scale=Math.max(.85,Math.min(1.25,v));document.documentElement.style.setProperty('--scale',scale);$('#zoomRead').textContent=Math.round(scale*100)+'%';localStorage.setItem('portfolioScale',scale)}
setScale(parseFloat(localStorage.getItem('portfolioScale'))||1);$('#zoomIn').onclick=()=>setScale(scale+.05);$('#zoomOut').onclick=()=>setScale(scale-.05);

// Program filters.
$$('.filter').forEach(btn=>btn.onclick=()=>{$$('.filter').forEach(b=>b.classList.remove('active'));btn.classList.add('active');const f=btn.dataset.filter;$$('.program').forEach(c=>c.hidden=f!=='all'&&c.dataset.sector!==f)});

// Case tabs.
$$('.case-tab').forEach(btn=>btn.onclick=()=>{$$('.case-tab').forEach(b=>b.classList.remove('active'));btn.classList.add('active');$$('.case-panel').forEach(p=>p.classList.remove('active'));$('#case-'+btn.dataset.case).classList.add('active')});

// Country map and relationship actions.
let selectedCountry='saudi-arabia';
function renderCountry(id){selectedCountry=id;const c=COUNTRY_DATA[id];$('#countryScope').textContent=c.scope;$('#countryName').textContent=c.name;$('#countryPeriod').textContent=c.period;$('#countrySummary').textContent=c.summary;$('#countryProjects').innerHTML=c.projects.map(x=>`<li>${x}</li>`).join('');$('#countryDeliverables').innerHTML=c.deliverables.map(x=>`<span class="chip">${x}</span>`).join('');
 $('#countryEvidence').innerHTML=c.evidence.length?c.evidence.map(e=>`<button class="evidence-link" onclick="openEvidence('${e}')">${EVIDENCE_META[e].type} ↗</button>`).join(''):'<span class="chip">Project details available in the linked portfolio section</span>';
 $$('.target-country').forEach(x=>x.classList.toggle('active',x.dataset.country===id));$$('.country-button').forEach(x=>x.classList.toggle('active',x.dataset.country===id));
 $('#countrySection').onclick=()=>{document.getElementById(c.section).scrollIntoView({behavior:'smooth'});highlight(document.getElementById(c.section))};
}
$$('[data-country].target-country,.country-button').forEach(x=>{x.onclick=()=>renderCountry(x.dataset.country);x.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();renderCountry(x.dataset.country)}}});renderCountry(selectedCountry);
let mapScale=1,mapX=0,mapY=0,drag=false,sx=0,sy=0;const map=$('#experienceMap'),stage=$('#mapStage');function applyMap(){map.style.transform=`translate(${mapX}px,${mapY}px) scale(${mapScale})`}
$('#mapPlus').onclick=()=>{mapScale=Math.min(3,mapScale+.25);applyMap()};$('#mapMinus').onclick=()=>{mapScale=Math.max(1,mapScale-.25);if(mapScale===1){mapX=mapY=0}applyMap()};$('#mapReset').onclick=()=>{mapScale=1;mapX=mapY=0;applyMap()};stage.addEventListener('wheel',e=>{e.preventDefault();mapScale=Math.max(1,Math.min(3,mapScale+(e.deltaY<0?.15:-.15)));if(mapScale===1){mapX=mapY=0}applyMap()},{passive:false});stage.onpointerdown=e=>{if(mapScale<=1)return;drag=true;sx=e.clientX-mapX;sy=e.clientY-mapY;stage.setPointerCapture(e.pointerId);stage.classList.add('dragging')};stage.onpointermove=e=>{if(!drag)return;mapX=e.clientX-sx;mapY=e.clientY-sy;applyMap()};stage.onpointerup=()=>{drag=false;stage.classList.remove('dragging')};

// Contextual search.
const searchItems=$$('[data-search-title]').map(el=>({el,title:el.dataset.searchTitle,text:(el.dataset.search||'')+' '+el.textContent.replace(/\s+/g,' ')}));
function openSearch(){$('#searchModal').classList.add('open');document.body.classList.add('lock');setTimeout(()=>$('#searchInput').focus(),50);renderSearch('')}
function closeSearch(){$('#searchModal').classList.remove('open');document.body.classList.remove('lock')}
function renderSearch(q){q=q.trim().toLowerCase();const res=q?searchItems.filter(x=>x.text.toLowerCase().includes(q)).slice(0,18):searchItems.slice(0,10);$('#searchResults').innerHTML=res.length?res.map((x,i)=>`<a href="#${x.el.id||''}" class="search-result" data-index="${searchItems.indexOf(x)}"><b>${x.title}</b><span>${x.text.slice(0,150)}…</span></a>`).join(''):'<div class="empty">No matching project, skill, country or deliverable was found.</div>';$$('.search-result').forEach(a=>a.onclick=e=>{e.preventDefault();const x=searchItems[+a.dataset.index];closeSearch();x.el.scrollIntoView({behavior:'smooth',block:'start'});highlight(x.el)})}
$('#searchButton').onclick=openSearch;$('#searchInput').oninput=e=>renderSearch(e.target.value);function highlight(el){el.classList.remove('highlight');void el.offsetWidth;el.classList.add('highlight');setTimeout(()=>el.classList.remove('highlight'),1900)}
addEventListener('keydown',e=>{if(e.key==='/'&&!/input|textarea/i.test(document.activeElement.tagName)){e.preventDefault();openSearch()}if(e.key==='Escape'){closeSearch();closeViewer();$('#mobileMenu').classList.remove('open')}});$('#searchModal').onclick=e=>{if(e.target===$('#searchModal'))closeSearch()};$('#viewer').onclick=e=>{if(e.target===$('#viewer'))closeViewer()};


function initJourneyStory(){
  const storyPeriod=document.getElementById('storyPeriod');
  const storyTitle=document.getElementById('storyTitle');
  const storyText=document.getElementById('storyText');
  const storySteps=document.getElementById('storySteps');
  const roles=document.querySelectorAll('#journey .role');
  if(!storyPeriod || !storyTitle || !storyText || !storySteps || !roles.length) return;
  const update=(role)=>{
    roles.forEach(item=>{ item.classList.remove('active'); item.setAttribute('aria-pressed','false');});
    role.classList.add('active');
    role.setAttribute('aria-pressed','true');
    storyPeriod.textContent=role.dataset.storyPeriod || '';
    storyTitle.textContent=role.dataset.storyTitle || '';
    storyText.textContent=role.dataset.storyText || '';
    const steps=(role.dataset.storySteps || '').split('|').filter(Boolean);
    storySteps.innerHTML=steps.map(step=>`<span>${step}</span>`).join('');
  };
  roles.forEach(role=>{
    role.addEventListener('click',()=>update(role));
    role.addEventListener('keydown',(e)=>{ if(e.key==='Enter' || e.key===' '){ e.preventDefault(); update(role); } });
  });
  const active=document.querySelector('#journey .role.active') || roles[0];
  update(active);
}
document.addEventListener('DOMContentLoaded', initJourneyStory);


// =====================================================================
// UI/UX REFINEMENT — PROFESSIONAL PORTFOLIO V6
// =====================================================================
(function(){
  const q=(s,r=document)=>r.querySelector(s), qa=(s,r=document)=>[...r.querySelectorAll(s)];
  const menu=q('#mobileMenu'), menuButton=q('#menuButton'), menuClose=q('#mobileMenuClose'), scrim=q('#menuScrim');
  if(menuButton)menuButton.onclick=null;
  const setMenu=(open)=>{
    if(!menu||!menuButton||!scrim)return;
    menu.classList.toggle('open',open);scrim.classList.toggle('open',open);
    menuButton.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-hidden',String(!open));
    if(open){document.body.classList.add('lock');setTimeout(()=>menuClose&&menuClose.focus(),60)}else{document.body.classList.remove('lock')}
  };
  if(menuButton) menuButton.addEventListener('click',()=>setMenu(!menu.classList.contains('open')));
  if(menuClose) menuClose.addEventListener('click',()=>setMenu(false));
  if(scrim) scrim.addEventListener('click',()=>setMenu(false));
  qa('#mobileMenu a').forEach(a=>{a.onclick=null;a.addEventListener('click',()=>setMenu(false))});

  const sectionNames={overview:'Overview',journey:'Career journey',capabilities:'Capabilities',impact:'Measurable impact',programs:'Programs',cases:'Case studies',countries:'Countries',works:'Selected works',automation:'Automation',evidence:'Live evidence',credentials:'Credentials',contact:'Contact'};
  const current=q('#currentSection'), header=q('.header');
  const updateHeader=()=>{
    const y=window.scrollY; if(header)header.classList.toggle('scrolled',y>24);
    let id='overview';qa('main section[id]').forEach(s=>{if(s.offsetTop<=y+150)id=s.id});
    if(current)current.textContent=sectionNames[id]||'Portfolio';
    qa('#mobileMenu a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+id));
  };
  window.addEventListener('scroll',updateHeader,{passive:true});updateHeader();

  // Program result count and accessible filter state.
  const updateProgramCount=()=>{
    const visible=qa('.program').filter(x=>!x.hidden).length, total=qa('.program').length;
    const counter=q('#programCount');if(counter)counter.textContent=`${visible} of ${total} programs shown`;
    qa('.filter').forEach(b=>b.setAttribute('aria-pressed',String(b.classList.contains('active'))));
  };
  qa('.filter').forEach(b=>b.addEventListener('click',()=>setTimeout(updateProgramCount,0)));updateProgramCount();

  // Accessible case tabs.
  qa('.case-tab').forEach(btn=>btn.addEventListener('click',()=>{
    qa('.case-tab').forEach(b=>b.setAttribute('aria-selected',String(b===btn)));
    const panel=q('#case-'+btn.dataset.case);if(panel)setTimeout(()=>panel.focus({preventScroll:true}),0);
  }));

  // Reveal high-level content progressively.
  const revealTargets=qa('.section-head,.outcome,.role,.expertise-card,.metric,.program,.case-main,.case-side,.agri-card,.work-feature,.mini-work,.relation-card,.automation-summary,.script-card,.evidence-card,.credential-card');
  revealTargets.forEach(el=>el.classList.add('ux-reveal'));
  if('IntersectionObserver' in window && !matchMedia('(prefers-reduced-motion: reduce)').matches){
    const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('ux-visible');io.unobserve(e.target)}}),{threshold:.08,rootMargin:'0px 0px -35px'});
    revealTargets.forEach(el=>io.observe(el));
  }else revealTargets.forEach(el=>el.classList.add('ux-visible'));

  // Keep evidence cards keyboard-friendly and make blank card areas actionable.
  const evidenceMap=[['GDB Analysis & Comparison Dashboard','gdb-analysis'],['International Standards for Database Design','standards'],['Automated GIS QA/QC Report Framework','qaqc'],['TerraPulse RS v5 Dashboard','terrapulse'],['Operational Dashboard Pro V09.1','ops-dashboard'],['Climate Analysis System','climate-system'],['Satellite Imagery Executive QA Report','satellite-qa-report'],['Hydro GIS System','hydro-gis-system'],['GeoAI Operational Dashboard','geoai-dashboard'],['Rainfed Agriculture App V02','rainfed-agric-app'],['GeoSite Dashboard','geosite-dashboard']];
  qa('.evidence-card').forEach(card=>{
    const title=(q('h3',card)?.textContent||'').trim();const hit=evidenceMap.find(x=>title.includes(x[0]));if(!hit)return;
    card.setAttribute('role','button');card.setAttribute('tabindex','0');
    card.addEventListener('click',e=>{if(e.target.closest('button,a,.evidence-preview'))return;openEvidence(hit[1])});
    card.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&!e.target.closest('button,a')){e.preventDefault();openEvidence(hit[1])}});
  });

  // Modal focus restoration.
  let lastFocus=null;
  const searchButton=q('#searchButton'), viewer=q('#viewer'), search=q('#searchModal');
  if(searchButton)searchButton.addEventListener('click',()=>{lastFocus=document.activeElement});
  qa('[onclick^="openEvidence"]').forEach(b=>b.addEventListener('click',()=>{lastFocus=document.activeElement}));
  const watchClose=new MutationObserver(()=>{
    if(search&&!search.classList.contains('open')&&viewer&&!viewer.classList.contains('open')&&lastFocus){try{lastFocus.focus()}catch(_){}lastFocus=null}
  });
  if(search)watchClose.observe(search,{attributes:true,attributeFilter:['class']});if(viewer)watchClose.observe(viewer,{attributes:true,attributeFilter:['class']});

  // Keyboard navigation for case tabs and filters.
  const roving=(selector)=>qa(selector).forEach((btn,i,list)=>btn.addEventListener('keydown',e=>{
    if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();
    let n=e.key==='Home'?0:e.key==='End'?list.length-1:(i+(e.key==='ArrowRight'?1:-1)+list.length)%list.length;list[n].focus();
  }));
  roving('.case-tab');roving('.filter');

  // Ensure Escape closes the redesigned mobile drawer too.
  window.addEventListener('keydown',e=>{if(e.key==='Escape')setMenu(false)});
})();
